function getProphetMetaTranslation(key, lang) {
    return (prophetmetaTranslations[lang] && prophetmetaTranslations[lang][key]) ||
           (prophetmetaTranslations.en && prophetmetaTranslations.en[key]) || null;
}

function applyProphetMetaTranslations(lang) {
    let count = 0;
    document.querySelectorAll("[data-i18n]").forEach(el => {
        const key = el.getAttribute("data-i18n");
        if (key && (key.startsWith("review.prophet-meta.") || key.startsWith("review.common."))) {
            const translation = getProphetMetaTranslation(key, lang);
            if (translation) { el.textContent = translation; count++; }
        }
    });
    
}

window.addEventListener("languageChanged", e => setTimeout(() => applyProphetMetaTranslations(e.detail.language), 200));

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => applyProphetMetaTranslations(window.i18n?.getCurrentLanguage() || "en"));
} else {
    applyProphetMetaTranslations(window.i18n?.getCurrentLanguage() || "en");
}
